    'fc.help_body' => 'A telefonról tárcsázható rövidkódok kezelése (pl. <code>*78</code>): Ne zavarjanak (DND), hívásátirányítás, csoportos/célzott hívásfelvétel, hívás lehallgatása, várólista be-/kilépés (<code>*81&lt;queue id&gt;</code> / <code>*80&lt;queue id&gt;</code>), várólista szüneteltetése / folytatása (<code>*22&lt;break id&gt;</code> / <code>*23</code>).',
