    'asterisk_settings.rtp_help_body' => 'Meghatározza, mely porttartomány szállítja a hangot (RTP), és hogy az Asterisk elutasítja-e a váratlan forrásból érkező hangot. Ezt a fájlt (<code>/etc/asterisk/rtp.conf</code>) mostantól a panel generálja; a szerveren végzett kézi módosítások a következő „Alkalmazás” során elvesznek.',
