    'trunks.connection_mode_help' => 'IP-alapú: a partnert az IP-címe azonosítja, és a kapcsolati címe (contact) statikus marad – ez az ajánlott mód az azonos hálózaton lévő, rögzített IP-vel rendelkező partnerhez. Bejövő regisztráció: a partner SIP REGISTER üzenetet küld nekünk, és a címét ebből a regisztrációból tanuljuk meg. Ehhez a módhoz felhasználónév és jelszó szükséges; a partner ezekkel hitelesíti a regisztrációját és a hívásait is.',
