    'sound_packs.tab' => 'Asterisk hangcsomagok',
    'sound_packs.title' => 'Hivatalos Asterisk hangcsomagok',
    'sound_packs.help_title' => 'Asterisk hangcsomagok',
    'sound_packs.help_body' => 'Letölti és telepíti az Asterisk hivatalos rendszerüzeneteit és tartási zenéit a <code>downloads.asterisk.org</code> oldalról. Minden csomag egy nyelvet tartalmaz egy formátumban; az Asterisk a hívás kodekjének megfelelő formátumot játssza le, egyébként átkódol (G.722-höz g722, szolgáltatókhoz ulaw/alaw).<br>- <strong>Alap:</strong> rendszerüzenetek, számjegyek, hangposta. <strong>Extra:</strong> további üzenetek; előbb ugyanannak a nyelvnek az alapcsomagját kell telepíteni.<br>- <strong>Tartási zene (opsound):</strong> a <code>/var/lib/asterisk/moh/opsound</code> könyvtárba települ; lejátszásához hozzon létre egy <strong>opsound</strong> nevű MOH osztályt a Tartási zene lapon.<br>- <strong>Türkçe (AiPBX):</strong> az AiPBX saját török nyelvű üzenetei (GitHub kiadás, SHA256-tal ellenőrizve); az alapértelmezett nyelv a török, így eltávolításuk elnémítja a rendszerüzeneteket. Az eltávolítás csak a csomag által telepített fájlokat törli.',
