    'ms_teams.guide_title' => 'Microsoft Teams integráció – útmutató',
    'ms_teams.guide_intro' => 'Az AiPBX két különböző szinten tud kommunikálni a Microsoft Teamsszel:',
    'ms_teams.guide_dr_title' => '1. Direct Routing (SBC / SIP trönk):',
    'ms_teams.guide_dr_desc' => 'Lehetővé teszi, hogy a Teams-felhasználók közvetlenül a Teams asztali/mobil tárcsázójáról indítsanak és fogadjanak belső és külső hívásokat. TLS (5061-es port), SRTP és érvényes nyilvános SSL-tanúsítvány (pl. Let\'s Encrypt) szükséges hozzá.',
    'ms_teams.guide_webhook_title' => '2. Webhookok és csatornaértesítések:',
    'ms_teams.guide_webhook_desc' => 'Interaktív Adaptive Card kártyákat küld a kijelölt Teams-csatornákra nem fogadott hívásokról, hangpostaüzenetekről, bejövő faxokról és ügyfélszolgálati riasztásokról. Nem igényel telefonos licencet.',
