    'certificates.help_body' => 'A portál (HTTPS), a WebRTC TURNS és a SIP-TLS/WSS egyetlen közös tanúsítványt használ; az itt végzett módosítások egyszerre érvényesülnek az Apache, a coturn és az Asterisk esetében. A <b>Let\'s Encrypt</b> ingyenes és automatikusan megújul; a tartománynak erre a szerverre kell mutatnia, és a 80-as portnak elérhetőnek kell lennie az internetről. Ha szervezetének saját tanúsítványa van, <b>töltse fel</b> (PEM vagy PFX); a feltöltött tanúsítványok nem újulnak meg automatikusan, lejárat előtt töltsön fel újat. <b>Önaláírt</b> tanúsítvány esetén a böngészők figyelmeztetést jelenítenek meg, és a TURNS nem működik böngészőkben: a tűzfal mögötti WebRTC-hívásoknál előfordulhat, hogy nincs hang.',
