    'queue_reports.help_body' => 'Minden várólistába érkező hívás egyszer számít. <b>Fogadott</b>: ügynökhöz kapcsolva. <b>Elveszett</b>: a hívó várakozás közben bontott, vagy a várólista ideje lejárt. <b>Rövid feladás</b>: %d másodpercen belül bontott; kimarad a szolgáltatási szintből. <b>Szolgáltatási szint</b>: a célidőn belül fogadott hívások aránya az összes hívásból, a rövid feladások kivételével. <b>ASA</b>: a fogadott hívások átlagos várakozási ideje. <b>AHT</b>: átlagos beszélgetési idő. <b>Felvételi arány</b> (ügynök): milyen gyakran vette fel az ügynök, amikor a várólista megcsengette. <b>Visszahívás</b>: egy elveszett hívás megoldottnak számít, ha a számot később egy mellékről felhívták, vagy a hívó újra hívott és fogadták. Az adatok az Asterisk várólistanaplójából származnak; a riport letölthető PDF vagy Excel formátumban.',
