    'ai_apps.help_body' => 'Az MI-alkalmazás fogadja a hívást, elvégzi a feladatát, majd továbbítja a hívást egy célállomásra. Adjon meg egy belső számot a közvetlen tárcsázáshoz, vagy válassza ki célként az IVR-ekben, bejövő útvonalakban és időfeltételekben („MI-alkalmazás”). <strong>Bemondás értékekkel</strong>: egy szöveg, amelyet a szerver hangmodellje olvas fel a hívónak behelyettesített értékekkel — a {caller_number}, {caller_name}, {did} a hívásból származik, bármely más {name} pedig a saját rendszeréből a lekérdezési címen keresztül. A változtatások az <strong>Alkalmazás</strong> gombbal lépnek életbe.',
