    'ai_cloud.help_body' => 'A felhőalapú MI-szolgáltatók fiókjai egy helyen: beszédkészítés, beszédfelismerés, nyelvi modellek (Gemini, Gemma, GPT, Llama …) és beágyazások (embeddings). Adjon meg egy kulcsot, tesztelje, és válassza ki az egyes feladatokhoz és nyelvekhez használt motort: a szerver helyi modelljét vagy egy felhőszolgáltatót. Az ingyenes keretek jelölve vannak; a havi használat minden szolgáltatónál megjelenik.',
