    'ai_tts.help_body' => 'Felhőszolgáltatások (Google, Amazon Polly, Azure, ElevenLabs, OpenAI) segítségével természetes beszéddé alakítja a szöveget. Hallgassa meg az eredményt, töltse le MP3-ként, vagy mentse egy kattintással <b>bemondásként</b>: Asterisk formátumra (8 kHz WAV) konvertálódik, és bekerül a Hangok &amp; bemondások közé IVR-ekhez, bejövő útvonalakhoz és időfeltételekhez (az Alkalmazás után lép életbe). <b>Ezek a szolgáltatások fizetősek</b>, és karakterenként számláznak; minden szintézis a karakterszámmal együtt megmarad az előzményekben. A hozzáférési kulcsok az egyes szolgáltatók konzoljából származnak, titkosítva tárolódnak, és többé nem jelennek meg az oldalon.',
