    'storage.help_title' => 'Hol tárolódnak a csevegőfájlok',
    'storage.help_body' => '<p>A csevegőmellékletek, azok bélyegképei és a csoportképek alapértelmezés szerint a szerver lemezén tárolódnak (<code>/var/lib/aipbx/chat_files</code>). S3-kompatibilis tárolóval (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …) ehelyett egy bucketbe kerülnek, így a nagy fájlok nem terhelik a PBX-et.</p><p>A letöltések továbbra is a csevegőszolgáltatáson keresztül történnek, így egy csevegés fájljait csak a résztvevői nyithatják meg; a bucket maradhat privát. Az átállás előtt tárolt fájlokat a rendszer továbbra is a lemezről szolgálja ki, amíg át nem helyezi őket. A bucket beállításait mentés előtt ellenőrizzük.</p><p>A hívásfelvételek, a hangposta és a faxok a helyi lemezen maradnak.</p>',
