    'netsvc.help_body' => 'Az asztali telefonok maguktól megtalálják a provisioning szervert, ha a DHCP szerver kiosztja annak címét (66-os opció). A DHCP és a TFTP külön kapcsolható be. Kikapcsolt <strong>DHCP szerver</strong> esetén a saját DHCP szervere marad: ott állítsa be az alább felsorolt opciókat. Bekapcsolva az AiPBX egy interfészen vagy VLAN-on oszt ki címeket. A <strong>TFTP szerver</strong> a feltöltött boot fájlokat és firmware-t szolgálja ki. A telefononkénti konfiguráció (a SIP jelszóval) mindig HTTPS-en keresztül érhető el, soha nem TFTP-n.',
