    'web_widgets.help_body' => 'A widget egy "Hívjon minket" gombot helyez el bármely weboldalon. A látogatók a böngészőből, WebRTC-n keresztül beszélhetnek Önnel, vagy megadhatják a számukat, és a PBX visszahívja őket. Illessze be az egysoros kódot a weboldalba (vagy a WordPress bővítménybe), és mentés után nyomja meg az <strong>Alkalmazás</strong> gombot.',
